export type MxIconName = keyof typeof MX_ICONS;

/** Resolves the bold counterpart of an icon name (e.g. 'document-outline' -> 'document-bold').
 *  Returns null when the icon family has no bold variant (e.g. hamburger-menu-outline). */
export function mxBoldName(name: MxIconName): MxIconName | null {
	const bold = name.replace(/(outline|linear)$/, 'bold');
	return (bold in MX_ICONS ? bold : null) as MxIconName | null;
}
